let state=null,tickTimer=null,analyticsRange='week',page=localStorage.getItem('torqueclockPage')||'home',theme=localStorage.getItem('torqueclockTheme')||'shop',selectedItems=[],selectedPackage='';
let session=JSON.parse(localStorage.getItem('torqueclockSession')||'null'),authMode='login',authError='',authBusy=false,pwError='',pwBusy=false;
function clearSession(){session=null;state=null;localStorage.removeItem('torqueclockSession')}
function me(){return(state&&state.me)||{username:'',role:'tech',laborRate:0,goals:{}}}
function bookRates(){return(state&&state.presets&&state.presets.book)||{}}
function jsq(s){return String(s??'').replace(/\\/g,'\\\\').replace(/'/g,"\\'")}
