const app=()=>document.getElementById('app');
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function enc(s){return encodeURIComponent(s||'')}function dec(s){return decodeURIComponent(s||'')}
function ms(a,b=new Date()){return a?new Date(b)-new Date(a):0}
function fmt(x){x=Math.max(0,Math.floor(x/1000));let h=Math.floor(x/3600),m=Math.floor(x%3600/60),s=x%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`}
function hrs(x){return (x/3600000).toFixed(2)}
function clock(){return new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',second:'2-digit',hour12:true})}
function tm(x){return x?new Date(x).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',hour12:true}):'now'}
function sh(){return state&&state.activeShift}function jobsOf(s){return (s&&s.jobs)||[]}function heldJobs(){return jobsOf(sh()).filter(j=>!j.end&&j.status==='hold')}function job(){let s=sh();if(!s)return null;let a=jobsOf(s);for(let i=a.length-1;i>=0;i--)if(!a[i].end&&a[i].status!=='hold')return a[i];return null}
function activeTask(j){if(!j)return null;for(const t of (j.tasks||[])){let segs=t.segments||[];if(segs.length&&!segs[segs.length-1].end)return t}return null}
function openWait(j){let w=(j&&j.waits)||[];return w.length&&!w[w.length-1].end?w[w.length-1]:null}function openBreak(s){let b=(s&&s.breaks)||[];for(let i=b.length-1;i>=0;i--)if(!b[i].end)return b[i];return null}
function sumSegs(segs){return (segs||[]).reduce((a,s)=>a+ms(s.start,s.end||new Date()),0)}function taskTotal(t){return sumSegs(t.segments)}function jobStats(j){let work=(j.tasks||[]).reduce((a,t)=>a+taskTotal(t),0),wait=sumSegs(j.waits);return{work,wait,total:ms(j.start,j.end||new Date())}}
function totals(s){let total=s?ms(s.start,s.end||new Date()):0,work=0,wait=0,breaks=0;if(!s)return{total,work,wait,breaks};(s.breaks||[]).forEach(b=>breaks+=ms(b.start,b.end||new Date()));jobsOf(s).forEach(j=>{let x=jobStats(j);work+=x.work;wait+=x.wait});return{total,work,wait,breaks}}
async function api(payload){let r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-Session-Token':session?.token||''},body:JSON.stringify(payload)});if(r.status===401){clearSession();render();return{ok:false,message:'Session expired, please log in again'}}let j=await r.json();if(!j.ok)toast(j.message||j.error||'Nope');state=j.state;render();return j}
function canFullRender(){let e=document.activeElement;if(!e)return true;if(['SELECT','INPUT','TEXTAREA'].includes(e.tagName))return false;return true}
function safeTick(){if(canFullRender()&&(page==='home'||page==='work'||page==='analytics'||page==='results'))render()}
async function migrateLocalBookRates(){let raw=localStorage.getItem('torqueclockBookRates');if(!raw)return;try{let old=JSON.parse(raw);for(const[label,hours]of Object.entries(old||{})){if(!(label in bookRates())&&hours>0)await api({action:'setBookRate',label,hours})}}catch(e){}localStorage.removeItem('torqueclockBookRates')}
async function load(){if(!session){render();return}try{let r=await fetch('/api/state',{headers:{'X-Session-Token':session.token}});if(r.status===401){clearSession();render();return}state=await r.json();applyTheme(theme);render();clearInterval(tickTimer);tickTimer=setInterval(safeTick,1000);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});migrateLocalBookRates()}catch(e){app().innerHTML=`<main class="screen"><section class="card"><h1>Server not reachable</h1><p>${esc(e)}</p></section></main>`}}
async function authSubmit(){let u=($('#authUser')?.value||'').trim(),pw=$('#authPass')?.value||'';if(!u||!pw){authError='Enter a username and password';render();return}if(authMode==='register'&&pw.length<6){authError='Password must be at least 6 characters';render();return}authBusy=true;authError='';render();try{let r=await fetch(authMode==='register'?'/api/register':'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:pw})}),j=await r.json();authBusy=false;if(!j.ok){authError=j.message||'Could not log in';render();return}session={token:j.token,username:j.username};localStorage.setItem('torqueclockSession',JSON.stringify(session));authError='';load()}catch(e){authBusy=false;authError='Server not reachable';render()}}
function switchAuthMode(m){authMode=m;authError='';render()}
async function doLogout(){try{await fetch('/api/logout',{method:'POST',headers:{'X-Session-Token':session?.token||'','Content-Type':'application/json'},body:'{}'})}catch(e){}clearSession();page='home';render()}
async function changePasswordSubmit(){let cur=$('#pwCurrent')?.value||'',nw=$('#pwNew')?.value||'';if(nw.length<6){pwError='New password must be at least 6 characters';render();return}pwBusy=true;pwError='';render();let r=await api({action:'changePassword',current:cur,new:nw});pwBusy=false;if(r.ok){pwError='';toast('Password changed')}else{pwError=r.message||'Could not change password'}render()}
function loginScreen(){return `<div class="appShell"><main class="screen"><section class="heroCard"><div><span class="eyebrow">TorqueClock</span><h1>${authMode==='register'?'Create account':'Log in'}</h1><p>Flat-rate time tracking, saved per tech.</p></div></section><section class="card formCard"><label>Username<input id="authUser" value="" placeholder="e.g. CAK3D" autocapitalize="none" autocomplete="username"></label><label>Password<input id="authPass" type="password" placeholder="Password" autocomplete="${authMode==='register'?'new-password':'current-password'}" onkeydown="if(event.key==='Enter')authSubmit()"></label>${authError?`<p style="color:var(--bad);font-weight:800">${esc(authError)}</p>`:''}<button class="go" ${authBusy?'disabled':''} onclick="authSubmit()">${authBusy?'Please wait…':(authMode==='register'?'Create account':'Log in')}</button><button class="secondary" onclick="switchAuthMode('${authMode==='register'?'login':'register'}')">${authMode==='register'?'Already have an account? Log in':'New here? Create an account'}</button></section></main></div>`}
function toast(t){let d=document.createElement('div');d.className='toast';d.textContent=t;document.body.appendChild(d);setTimeout(()=>d.remove(),2500)}
function applyTheme(t){theme=t;localStorage.setItem('torqueclockTheme',t);document.documentElement.dataset.theme=t}
function go(p){page=p;localStorage.setItem('torqueclockPage',p);render()}function back(){let map={day:'schedule',schedule:'home',vehicle:'work',package:'vehicle',review:'package',work:'home',focus:'work',quick:'home',settings:'home',analytics:'home',results:'home'};go(map[page]||'home')}
function statusText(){let s=sh(),j=job(),br=openBreak(s);return br?br.label:j?'Working W/O':s?'Clocked in':'Off clock'}
function opts(a,ph,val=''){return `<option value="" ${val===''?'selected':''}>${ph}</option>`+a.map(x=>`<option value="${esc(x)}" ${String(x)===String(val)?'selected':''}>${esc(x)}</option>`).join('')}
function years(){let y=new Date().getFullYear()+1,a=[];for(let i=y;i>=1980;i--)a.push(String(i));return a}
function withCustom(a){return [...a,'Custom']}
function isCustom(v){return v==='Custom'}
function actualMake(){return (isCustom(draft.make)?draft.customMake:draft.make)||''}
function actualModel(){return (isCustom(draft.model)?draft.customModel:draft.model)||''}
function actualTrim(){return (isCustom(draft.trim)?draft.customTrim:draft.trim)||''}
function actualFrom(d,k){return (isCustom(d[k])?d['custom'+k[0].toUpperCase()+k.slice(1)]:d[k])||''}
function trimOptionsFor(d){let m=actualFrom(d,'make'),mo=actualFrom(d,'model');return trims[`${m}|${mo}`]||[]}
function trimOptions(){let m=actualMake(),mo=actualModel();return trims[`${m}|${mo}`]||[]}
function dtLocal(x){if(!x)return '';let d=new Date(x);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function isoFromLocal(v){return v?new Date(v).toISOString():''}
function pageTitle(){return {home:'Home',schedule:'Calendar schedule',day:'Day setup',vehicle:'Step 1: Vehicle',package:'Step 2: W/O Package',review:'Step 3: Review',work:'Work timers',quick:'Quick view',settings:'Settings',analytics:'Analytics',focus:'Focus mode',results:'History'}[page]||'TorqueClock'}
function bookMsFor(label){let v=bookRates()[label];if(v==null)v=defaultBook[label];return Number(v||0)*3600000}
function jobBookMs(j){return (j?.tasks||[]).reduce((a,t)=>a+bookMsFor(t.label),0)}
function paceInfo(j){let st=jobStats(j),book=jobBookMs(j),delta=book-st.work,pct=book?Math.round(st.work/book*100):0;return{book,delta,pct,work:st.work}}
function paceText(j){let p=paceInfo(j);if(!p.book)return 'Add book time for pace';return p.delta>=0?`Ahead by ${fmt(p.delta)}`:`Behind by ${fmt(Math.abs(p.delta))}`}
function effPct(billedMs,actualMs){return actualMs>0?Math.round(billedMs/actualMs*100):null}
function effClass(p){return p==null?'effNone':p>=100?'effGood':p>=85?'effWarn':'effBad'}
function effLabel(p){return p==null?'No target':p+'%'}
function effChip(p){return `<span class="effBadge ${effClass(p)}">${effLabel(p)}</span>`}
function aggEff(rows){let hoursMs=0,billed=0,actual=0;rows.forEach(r=>{hoursMs+=r.dur;if(r.bookMs>0){billed+=r.bookMs;actual+=r.dur}});return{hoursMs,billed,actual,pct:effPct(billed,actual)}}
function dollars(ms,rate){return(ms/3600000*(rate||0)).toFixed(2)}
async function saveLaborRate(val){let n=parseFloat(val);await api({action:'setLaborRate',rate:Number.isFinite(n)?n:0});toast('Labor rate saved')}
async function saveGoal(val){let n=parseFloat(val);await api({action:'setGoal',targetEfficiencyPct:Number.isFinite(n)?n:0});toast('Goal saved')}
function goalBar(pct,goal){let g=goal||95,cur=pct==null?0:pct,fillPct=Math.max(2,Math.min(100,cur/Math.max(g,1)*100)),hit=cur>=g;return `<div class="beatMeter" style="margin-top:14px"><span>0%</span><i style="background:linear-gradient(90deg,var(--bad),var(--warn),var(--good))"><b style="left:${fillPct}%;border-color:${hit?'var(--good)':'var(--hot)'}"></b></i><span>Goal ${g}%</span></div><p class="muted">${pct==null?'No billed hours yet in this range.':hit?`Hit your ${g}% goal.`:`${(g-cur).toFixed(0)} pts short of your ${g}% goal.`}</p>`}
function nowBar(){let s=sh(),j=job(),br=openBreak(s);if(!s)return '';let run=activeTask(j),wait=openWait(j),title=br?`BREAK: ${esc(br.label)} · ${fmt(ms(br.start))}`:wait?`WAITING: ${esc(wait.label)} · ${fmt(ms(wait.start))}`:run?`NOW WRENCHING: ${esc(run.label)} · ${fmt(taskTotal(run))}`:j?`W/O READY: ${esc(j.vehicle||'Vehicle')}`:'CLOCKED IN: build or pick a W/O';let sub=j?`${esc(j.vehicle||'Vehicle')} ${j.ro?'· RO '+esc(j.ro):''}`:'No active W/O';return `<div class="nowBar"><button class="nowText" onclick="go('${j?'focus':'work'}')"><b>${title}</b><span>${sub}</span></button><div class="nowBtns">${j&&!wait?`<button class="warn" onclick="api({action:'startWait',label:'Parts'})">Wait</button>`:''}${j?`<button class="go" onclick="go('focus')">Focus</button>`:`<button class="go" onclick="go('work')">Create W/O</button>`}</div></div>`}
function morningSetupPanel(){let s=sh(),today=openScheduleItems(todayKey());if(!s||job())return '';return `<section class="card morning"><span class="eyebrow">Morning setup</span><h2>Build today’s board before the first ticket.</h2><p class="muted">${today.length?`${today.length} W/O staged for today.`:'No W/O staged yet. Pull from schedule or create one fresh.'}</p><div class="actionRow"><button class="go" onclick="go('day')">Open today</button><button class="secondary" onclick="go('vehicle')">Create W/O</button></div></section>`}
function woTicket(j){let st=jobStats(j),run=activeTask(j),wait=openWait(j),p=paceInfo(j);return `<section class="card ticketCard"><div class="ticketTop"><span>REPAIR ORDER</span><b>${j.ro?esc(j.ro):'NO RO'}</b><em>${esc(j.status||'active')}</em></div><h2>${esc(j.vehicle||'Vehicle')}</h2><p>${esc(j.title||'W/O')} ${j.category?'· '+esc(j.category):''}</p><div class="metrics three"><div><span>Wrench</span><b>${fmt(st.work)}</b></div><div><span>Wait drag</span><b>${fmt(st.wait)}</b></div><div><span>Book pace</span><b>${p.book?esc(paceText(j)):'—'}</b></div></div><div class="beatMeter"><span>Behind</span><i><b style="left:${p.book?Math.max(2,Math.min(98,100-(st.work/p.book*100))):50}%"></b></i><span>Beating book</span></div></section>`}
function timelineEvents(j){let ev=[];if(!j)return ev;if(j.start)ev.push({at:j.start,label:'W/O started'});(j.tasks||[]).forEach(t=>(t.segments||[]).forEach(seg=>{ev.push({at:seg.start,label:`${t.label} started`});if(seg.end)ev.push({at:seg.end,label:`${t.label} paused/done`})}));(j.waits||[]).forEach(w=>{ev.push({at:w.start,label:`Waiting: ${w.label}`});if(w.end)ev.push({at:w.end,label:`Back from ${w.label}`})});if(j.end)ev.push({at:j.end,label:'W/O finished'});return ev.filter(e=>e.at).sort((a,b)=>new Date(a.at)-new Date(b.at))}
function jobTimeline(j){let ev=timelineEvents(j);return `<section class="card timeline"><h2>What happened?</h2>${ev.length?ev.slice(-10).map(e=>`<div><time>${tm(e.at)}</time><span>${esc(e.label)}</span></div>`).join(''):'<p class="muted">Start a timer and this W/O will build its own timeline.</p>'}</section>`}
function waitDragBreakdown(rows=allShifts().flatMap(s=>jobsOf(s))){let m={};rows.forEach(j=>(j.waits||[]).forEach(w=>{m[w.label]=(m[w.label]||0)+ms(w.start,w.end||new Date())}));let a=Object.entries(m).sort((x,y)=>y[1]-x[1]).slice(0,6);return `<section class="card"><h2>Wait drag</h2>${a.length?a.map(([k,v])=>`<div class="dragRow"><span>${esc(k)}</span><b>${fmt(v)}</b></div>`).join(''):'<p class="muted">No wait drag logged yet. Use reason chips like Parts, Approval, Rack, Advisor.</p>'}</section>`}
function focusScreen(){let j=job(),s=sh();if(!j)return workStartScreen();let run=activeTask(j),wait=openWait(j),st=jobStats(j);return `<section class="focusHero"><span>${wait?'WAITING':run?'NOW WRENCHING':'READY'}</span><h1>${esc(run?.label||wait?.label||j.title||'W/O')}</h1><b>${wait?fmt(ms(wait.start)):run?fmt(taskTotal(run)):fmt(st.total)}</b><p>${esc(j.vehicle||'Vehicle')} ${j.ro?'· RO '+esc(j.ro):''}</p></section><section class="focusButtons"><button class="warn" onclick="api({action:'holdJob'}).then(()=>go('home'))">Park vehicle</button>${wait?`<button class="go" onclick="api({action:'endWait'})">Back on it</button>`:`<button class="warn" onclick="api({action:'startWait',label:'Parts'})">Waiting on parts</button>`}<button class="secondary" onclick="go('work')">All timers</button><button class="danger" onclick="api({action:'endJob'}).then(()=>go('home'))">Finish job</button></section>${woTicket(j)}${jobTimeline(j)}`}

function render(){if(!session){app().innerHTML=loginScreen();return}if(!state)return;let s=sh(),j=job(),br=openBreak(s);app().innerHTML=`<div class="appShell"><header class="top"><button class="backBtn" ${page==='home'?'disabled':''} onclick="back()">← Back</button><div><b>${pageTitle()}</b><span>${statusText()} • ${esc(me().username)}</span></div><button class="quickBtn" onclick="go('quick')">Quick Cal</button></header>${nowBar()}<main class="screen">${screen()}</main><nav class="nav"><button class="${page==='home'?'on':''}" onclick="go('home')">Home</button><button class="${page==='schedule'?'on':''}" onclick="go('schedule')">Schedule</button><button class="${page==='vehicle'||page==='package'||page==='review'||page==='work'||page==='focus'?'on':''}" onclick="go('work')">Work</button><button class="${page==='analytics'?'on':''}" onclick="go('analytics')">Score</button><button class="${page==='settings'?'on':''}" onclick="go('settings')">Settings</button></nav></div>`}
function screen(){if(page==='schedule')return scheduleScreen();if(page==='day')return dayScreen();if(page==='vehicle')return vehicleScreen();if(page==='package')return packageScreen();if(page==='review')return reviewScreen();if(page==='work')return workScreen();if(page==='focus')return focusScreen();if(page==='quick')return quickScreen();if(page==='settings')return settingsScreen();if(page==='analytics')return analyticsScreen();if(page==='results')return resultsScreen();return homeScreen()}
function recentJobs(n=4){return allShifts().flatMap(s=>jobsOf(s)).filter(j=>j.vehicle||j.title).sort((a,b)=>new Date(b.start||0)-new Date(a.start||0)).slice(0,n)}function repeatJob(j){if(!j)return;draft.year=j.year||'';draft.make=j.make||'';draft.model=j.model||'';draft.customMake=j.make&&!makes[j.make]?j.make:'';draft.customModel=j.model&&!(makes[j.make]||[]).includes(j.model)?j.model:'';draft.trim=j.trim||'';draft.customTrim=j.trim&&!(trims[`${j.make}|${j.model}`]||[]).includes(j.trim)?j.trim:'';draft.ro='';selectedPackage=j.title||'';selectedItems=(j.tasks||[]).map(t=>t.label).filter(Boolean);go('review')}function icon(n){return {car:'🚗',clock:'⏱️',park:'🅿️',chart:'📊',bolt:'⚡',save:'💾'}[n]||'•'}function homeScreen(){let s=sh(),j=job(),t=totals(s),br=openBreak(s),held=heldJobs();return `<section class="heroCard"><div><span class="eyebrow">TorqueClock</span><h1>${s?'Bay is open':'Ready to clock in'}</h1><p>${j?`${esc(j.vehicle||'Vehicle')} • ${esc(j.title)}`:br?`On ${esc(br.label)}`:''}</p></div><div class="heroTime">${clock()}</div></section><section class="bigGrid"><button class="mega ${s?'danger':'go'}" onclick="api({action:'${s?'stopShift':'startShift'}'})">${s?'Clock out':'Clock in'}</button><button class="mega" onclick="go('work')">${j?'Open work timers':'Start W/O'}</button></section><section class="card"><h2>At-a-glance</h2><div class="metrics"><div><span>Shift</span><b>${fmt(t.total)}</b></div><div><span>Wrench</span><b>${fmt(t.work)}</b></div><div><span>Wait</span><b>${fmt(t.wait)}</b></div><div><span>Break</span><b>${fmt(t.breaks)}</b></div></div></section>${morningSetupPanel()}${j?woTicket(j):''}${j?activeJobMini(j):''}${heldPanel()}${tallyPanel()}`}
function activeJobMini(j){let st=jobStats(j),run=activeTask(j),wait=openWait(j);return `<section class="card accent"><h2>Current W/O</h2><p><b>${esc(j.vehicle||'Vehicle')}</b><br>${esc(j.title)} ${j.ro?'• RO '+esc(j.ro):''}</p><div class="metrics two"><div><span>Total</span><b>${fmt(st.total)}</b></div><div><span>Now</span><b>${run?esc(run.label):wait?'WAIT':'Idle'}</b></div></div><div class="actionRow"><button class="go" onclick="go('focus')">Focus mode</button><button class="secondary" onclick="go('work')">All timers</button></div></section>`}
function heldPanel(){let h=heldJobs();return `<section class="card"><h2>Parked vehicles <span class="pill">${h.length}/3</span></h2>${h.length?h.map(j=>`<div class="listItem"><div><b>${esc(j.vehicle||'Vehicle')}</b><span>${esc(j.title)} • parked ${tm(j.heldAt)}</span></div><div class="miniBtns"><button onclick="api({action:'resumeJob',jobId:'${j.id}'}).then(()=>go('work'))">Resume</button><button class="secondary" onclick="deleteJob('${j.id}')">Remove</button></div></div>`).join(''):'<p class="muted">No parked vehicles.</p>'}</section>`}
function todayKey(){return new Date().toISOString().slice(0,10)}
function scheduleDay(date=selectedScheduleDate){return (((state||{}).schedule||{})[date]||{date,status:'',note:'',startTime:'08:00',endTime:'17:00',items:[]})}
function scheduleItems(date=selectedScheduleDate){return (scheduleDay(date).items)||[]}
function openScheduleItems(date=selectedScheduleDate){return scheduleItems(date).filter(x=>x.status!=='done')}
function scheduleCounts(){let m={};scheduleCats.forEach(c=>m[c]=0);openScheduleItems().forEach(x=>m[x.category]=(m[x.category]||0)+1);return m}
function scheduleItemPreview(it){return (it.items||[]).slice(0,3).join(', ')+((it.items||[]).length>3?'…':'')}
function dayClass(date){let d=scheduleDay(date),n=(d.items||[]).filter(x=>x.status!=='done').length;return `${d.status||''} ${n?'hasWo':''} ${date===selectedScheduleDate?'selected':''}`}
function calendarDays(){let first=new Date(calendarMonth+'-01T00:00:00'),start=new Date(first);start.setDate(1-first.getDay());let out=[];for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);out.push(d.toISOString().slice(0,10))}return out}
function monthShift(n){let d=new Date(calendarMonth+'-01T00:00:00');d.setMonth(d.getMonth()+n);calendarMonth=d.toISOString().slice(0,7);render()}
function selectScheduleDate(d){selectedScheduleDate=d;scheduleDraft.date=d;calendarMonth=d.slice(0,7);dayDropdownOpen=true;render()}
function calendarView(){let names=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<section class="card calendarCard"><div class="calHead"><button class="secondary" onclick="monthShift(-1)">‹</button><h2>${esc(calendarMonth)}</h2><button class="secondary" onclick="monthShift(1)">›</button></div><div class="calendarGrid names">${names.map(n=>`<b>${n}</b>`).join('')}</div><div class="calendarGrid">${calendarDays().map(d=>{let rec=scheduleDay(d),left=(rec.items||[]).filter(x=>x.status!=='done').length;return `<button class="calDay ${dayClass(d)}" onclick="selectScheduleDate('${d}')"><span>${Number(d.slice(8))}</span><em>${esc(rec.status||'')}</em>${left?`<strong>${left} W/O</strong>`:''}</button>`}).join('')}</div>${dayDropdownOpen?selectedDayDropdown():''}</section>`}
function scheduleCard(it){let done=it.status==='done',active=it.status==='active';return `<div class="scheduleItem ${done?'done':''} ${active?'active':''}"><div><b>${esc(it.vehicle||'Vehicle TBD')}</b><span>${esc(it.category||'General Service')} • ${esc(it.ro?'RO '+it.ro:'No RO')} • ${esc(it.title||'W/O')}</span><small>${esc(scheduleItemPreview(it)||it.notes||'No items listed')}</small></div><div class="miniBtns">${done?'<span class="pill">Done</span>':`<button class="go" onclick="startScheduledWorkOrder('${it.id}')">Start</button><button class="danger" onclick="deleteScheduledWorkOrder('${it.id}')">Delete</button>`}</div></div>`}
function scheduleBucket(cat,date=selectedScheduleDate){let items=scheduleItems(date).filter(x=>x.category===cat),open=items.filter(x=>x.status!=='done');return `<section class="card"><h2>${esc(cat)} <span class="pill">${open.length} left</span></h2>${items.length?items.map(scheduleCard).join(''):'<p class="muted">No W/O staged here yet.</p>'}</section>`}
function selectedDayDropdown(){let rec=scheduleDay(selectedScheduleDate),items=scheduleItems(selectedScheduleDate),open=items.filter(x=>x.status!=='done'),by=scheduleCats.map(c=>`${c}: ${open.filter(x=>x.category===c).length}`).join(' • ');return `<div class="dayDrop"><div><b>${esc(selectedScheduleDate)}</b><span class="pill">${esc(rec.status||'unscheduled')}</span></div><p class="muted">${esc(rec.note||'No day note yet')}<br>${esc((rec.startTime||'08:00')+' to '+(rec.endTime||'17:00'))}<br>${esc(by)}</p>${items.length?`<div class="dayDropList">${items.slice(0,5).map(x=>`<span>${esc(x.category)} — ${esc(x.vehicle||'Vehicle TBD')} ${x.status==='done'?'✓':''}</span>`).join('')}</div>`:'<p class="muted">No W/O on this day yet.</p>'}<div class="actionRow"><button class="go" onclick="go('day')">Open day</button><button class="secondary" onclick="dayDropdownOpen=false;render()">Close</button></div></div>`}

function scheduleVehicleFields(d,prefix='schedule'){let customMake=isCustom(d.make),models=customMake?[]:(makes[d.make]||[]),customModel=isCustom(d.model),trimList=trimOptionsFor(d),customTrim=isCustom(d.trim);return `<label>Year<select onchange="${prefix}Draft.year=this.value">${opts(years(),'Year',d.year)}</select></label><label>Make<select onchange="${prefix}Draft.make=this.value;${prefix}Draft.customMake='';${prefix}Draft.model='';${prefix}Draft.customModel='';${prefix}Draft.trim='';${prefix}Draft.customTrim='';render()">${opts(withCustom(Object.keys(makes).sort()),'Make',d.make)}</select></label>${customMake?`<label>Custom make<input value="${esc(d.customMake)}" oninput="${prefix}Draft.customMake=this.value;${prefix}Draft.model='Custom';${prefix}Draft.trim='';render()" placeholder="Type make"></label>`:''}<label>Model<select onchange="${prefix}Draft.model=this.value;${prefix}Draft.customModel='';${prefix}Draft.trim='';${prefix}Draft.customTrim='';render()">${opts(withCustom(models),'Model',d.model)}</select></label>${customModel?`<label>Custom model<input value="${esc(d.customModel)}" oninput="${prefix}Draft.customModel=this.value;${prefix}Draft.trim='Custom';render()" placeholder="Type model"></label>`:''}<label>Submodel / trim<select onchange="${prefix}Draft.trim=this.value;${prefix}Draft.customTrim='';render()">${opts(withCustom(trimList),'Submodel / trim',d.trim)}</select></label>${customTrim?`<label>Custom submodel / trim<input value="${esc(d.customTrim)}" oninput="${prefix}Draft.customTrim=this.value" placeholder="Type trim"></label>`:''}`}
function dayEditor(){let d=scheduleDay(selectedScheduleDate);return `<section class="card formCard"><h2>Edit ${esc(selectedScheduleDate)}</h2><label>Day type<select onchange="api({action:'setScheduleDay',date:selectedScheduleDate,status:this.value,note:scheduleDay(selectedScheduleDate).note||'',startTime:scheduleDay(selectedScheduleDate).startTime||'08:00',endTime:scheduleDay(selectedScheduleDate).endTime||'17:00'})">${opts(dayStatuses,'Day type',d.status||'')}</select></label><div class="twoCol"><label>Start time<input type="time" value="${esc(d.startTime||'08:00')}" onchange="api({action:'setScheduleDay',date:selectedScheduleDate,status:scheduleDay(selectedScheduleDate).status||'work',note:scheduleDay(selectedScheduleDate).note||'',startTime:this.value,endTime:scheduleDay(selectedScheduleDate).endTime||'17:00'})"></label><label>End time<input type="time" value="${esc(d.endTime||'17:00')}" onchange="api({action:'setScheduleDay',date:selectedScheduleDate,status:scheduleDay(selectedScheduleDate).status||'work',note:scheduleDay(selectedScheduleDate).note||'',startTime:scheduleDay(selectedScheduleDate).startTime||'08:00',endTime:this.value})"></label></div><label>Day note<input value="${esc(d.note||'')}" onchange="api({action:'setScheduleDay',date:selectedScheduleDate,status:scheduleDay(selectedScheduleDate).status||'work',note:this.value,startTime:scheduleDay(selectedScheduleDate).startTime||'08:00',endTime:scheduleDay(selectedScheduleDate).endTime||'17:00'})" placeholder="Holiday, vacation, half day, time off, etc."></label></section>`}
function ensureRecurrenceDraft(){let old=recurrenceDraft,base={0:{enabled:true,status:'work',startTime:'08:00',endTime:'17:00',note:''},1:{enabled:true,status:'work',startTime:'08:00',endTime:'17:00',note:''},2:{enabled:true,status:'work',startTime:'08:00',endTime:'17:00',note:''},3:{enabled:true,status:'work',startTime:'08:00',endTime:'17:00',note:''},4:{enabled:true,status:'work',startTime:'08:00',endTime:'17:00',note:''},5:{enabled:false,status:'off',startTime:'',endTime:'',note:'Regular day off'},6:{enabled:false,status:'off',startTime:'',endTime:'',note:'Regular day off'}};if(!old.days){let days={};[0,1,2,3,4,5,6].forEach(w=>days[w]={enabled:(old.weekdays||[]).includes(w),status:old.status||base[w].status,startTime:old.startTime||base[w].startTime,endTime:old.endTime||base[w].endTime,note:old.note||base[w].note});recurrenceDraft={weeks:old.weeks||26,days};}else{[0,1,2,3,4,5,6].forEach(w=>recurrenceDraft.days[w]={...base[w],...(recurrenceDraft.days[w]||{})});recurrenceDraft.weeks=recurrenceDraft.weeks||26;}return recurrenceDraft}
function setRecurrenceDay(w,k,v){ensureRecurrenceDraft();recurrenceDraft.days[w][k]=v;if(k==='status'&&v==='off'&&!recurrenceDraft.days[w].note)recurrenceDraft.days[w].note='Regular day off';render()}
function recurrenceEditor(){let rd=ensureRecurrenceDraft(),names=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return `<section class="card formCard recurringCard compactRecurring"><div class="recurringHead"><div><h2>Weekly pattern</h2><p class="muted">Tap a day on/off, then set type and hours.</p></div><label>Weeks<input type="number" min="1" max="104" value="${esc(rd.weeks)}" oninput="recurrenceDraft.weeks=this.value"></label></div><div class="recurrenceRows compact">${names.map((n,w)=>{let d=rd.days[w],off=d.status==='off';return `<div class="recurrenceRow compact ${d.enabled?'on':'off'}"><button class="chipBtn ${d.enabled?'on':''}" onclick="toggleRecurrenceDay(${w})">${d.enabled?'✓':'+'} ${n}</button><select aria-label="${n} type" onchange="setRecurrenceDay(${w},'status',this.value)">${opts(dayStatuses,'Type',d.status)}</select><div class="timeRow"><input aria-label="${n} start" type="time" value="${esc(d.startTime||'')}" onchange="setRecurrenceDay(${w},'startTime',this.value)" ${off?'disabled':''}><span>to</span><input aria-label="${n} end" type="time" value="${esc(d.endTime||'')}" onchange="setRecurrenceDay(${w},'endTime',this.value)" ${off?'disabled':''}></div></div>`}).join('')}</div><button class="secondary compactApply" onclick="applyRecurringSchedule()">Apply pattern</button></section>`}
function scheduleAddForm(){let p=state?.presets||fallback,items=p.work||fallback.work;scheduleDraft.date=selectedScheduleDate;return `<section class="card formCard"><h2>Add W/O to ${esc(selectedScheduleDate)}</h2><p class="muted">Same W/O builder style as Work: vehicle, package, additions, then stage it on the calendar.</p>${scheduleVehicleFields(scheduleDraft,'schedule')}<label>Bucket<select onchange="scheduleDraft.category=this.value;render()">${opts(scheduleCats,'Bucket',scheduleDraft.category)}</select></label><label>RO / ticket<input value="${esc(scheduleDraft.ro)}" oninput="scheduleDraft.ro=this.value" placeholder="#12345"></label><label>Job package<select onchange="setSchedulePackage(this.value)">${opts(Object.keys(packages),'Package or Custom',scheduleDraft.title)}</select></label><label>Additions<select onchange="scheduleDraft.itemChoice=this.value;render()">${opts(withCustom(items),'Add addition',scheduleDraft.itemChoice)}</select></label>${scheduleDraft.itemChoice==='Custom'?`<label>Custom addition<input value="${esc(scheduleDraft.customItem)}" oninput="scheduleDraft.customItem=this.value" placeholder="Manual W/O item"></label>`:''}<button class="secondary" onclick="addScheduleItemChip()">Add addition</button><label>Notes<textarea oninput="scheduleDraft.notes=this.value" placeholder="Keys, advisor note, parts ETA, bay plan">${esc(scheduleDraft.notes)}</textarea></label><div class="chips">${scheduleDraft.items.length?scheduleDraft.items.map((x,i)=>`<button class="chipBtn" onclick="removeScheduleItemChip(${i})">${esc(x)} ✕</button>`).join(''):'<p class="muted">Pick a package or add additions.</p>'}</div><button class="go" onclick="saveScheduledWorkOrder()">Add W/O to calendar day</button></section>`}
function scheduleScreen(){return `<section class="stepHero"><span>Schedule</span><h1>Calendar scheduler</h1><p>Tap a day to peek at its W/O, status, and notes. Use Open day for the full Work-style day setup.</p></section>${calendarView()}`}
function dayScreen(){let rec=scheduleDay(selectedScheduleDate),left=openScheduleItems(selectedScheduleDate).length;return `<section class="stepHero work"><span>Day setup</span><h1>${esc(selectedScheduleDate)}</h1><p>Set the day type, add time off notes, and stage W/O just like the Work flow.</p></section><section class="card"><h2>${esc(selectedScheduleDate)} <span class="pill">${esc(rec.status||'unscheduled')}</span></h2><p class="muted">${left} scheduled W/O remaining for this day.</p><div class="actionRow"><button class="secondary" onclick="go('schedule')">Back to calendar</button><button class="go" onclick="go('work')">Open Work page</button></div></section>${dayEditor()}${scheduleAddForm()}${scheduleCats.map(c=>scheduleBucket(c,selectedScheduleDate)).join('')}`}
function toggleRecurrenceDay(w){ensureRecurrenceDraft();recurrenceDraft.days[w].enabled=!recurrenceDraft.days[w].enabled;render()}
function applyRecurringSchedule(){let rd=ensureRecurrenceDraft(),calls=Object.entries(rd.days).filter(([w,d])=>d.enabled).map(([w,d])=>api({action:'addRecurringSchedule',startDate:selectedScheduleDate,status:d.status,note:d.note,startTime:d.startTime,endTime:d.endTime,weeks:rd.weeks,weekdays:[Number(w)]}));if(!calls.length){toast('Pick at least one recurring day');return}Promise.all(calls).then(()=>toast('Recurring schedule applied'))}
function setSchedulePackage(v){scheduleDraft.title=v;scheduleDraft.items=v in packages?[...packages[v]]:scheduleDraft.items;render()}
function schedulePendingItem(){let sel=scheduleDraft.itemChoice||'',manual=(scheduleDraft.customItem||'').trim();return sel==='Custom'?manual:(manual||sel)}
function addScheduleItemChip(){let v=schedulePendingItem();if(v&&!scheduleDraft.items.includes(v)){scheduleDraft.items.push(v);scheduleDraft.itemChoice='';scheduleDraft.customItem='';render()}}
function removeScheduleItemChip(i){scheduleDraft.items.splice(i,1);render()}
function saveScheduledWorkOrder(){addScheduleItemChip();let make=actualFrom(scheduleDraft,'make'),model=actualFrom(scheduleDraft,'model'),trim=actualFrom(scheduleDraft,'trim');api({action:'addScheduledWorkOrder',date:selectedScheduleDate,category:scheduleDraft.category,year:scheduleDraft.year,make,model,trim,vehicle:scheduleDraft.vehicle,ro:scheduleDraft.ro,title:scheduleDraft.title,items:scheduleDraft.items,notes:scheduleDraft.notes}).then(r=>{if(r.ok){scheduleDraft={date:selectedScheduleDate,category:'General Service',year:'',make:'',model:'',customMake:'',customModel:'',trim:'',customTrim:'',vehicle:'',ro:'',title:'Custom',itemChoice:'',customItem:'',items:[],notes:''};go('schedule')}})}
function startScheduledWorkOrder(id){api({action:'startScheduledWorkOrder',itemId:id}).then(r=>{if(r.ok)go('work')})}
function deleteScheduledWorkOrder(id){if(confirm('Remove this W/O from the calendar schedule?'))api({action:'deleteScheduledWorkOrder',itemId:id})}
function vehicleScreen(){let customMake=isCustom(draft.make),make=actualMake(),models=customMake?[]:(makes[draft.make]||[]),customModel=isCustom(draft.model),trimList=trimOptions(),customTrim=isCustom(draft.trim);return `<section class="stepHero"><span>Step 1 of 3</span><h1>Pick the vehicle</h1><p>Choose listed values when available. Use Custom inside the dropdowns when the exact make, model, submodel, or trim is missing.</p></section><section class="card formCard"><label>Year<select id="year" onchange="draft.year=this.value">${opts(years(),'Year',draft.year)}</select></label><label>Make<select id="make" onchange="draft.make=this.value;draft.customMake='';draft.model='';draft.customModel='';draft.trim='';draft.customTrim='';render()">${opts(withCustom(Object.keys(makes).sort()),'Make',draft.make)}</select></label>${customMake?`<label>Custom make<input id="customMake" value="${esc(draft.customMake)}" oninput="draft.customMake=this.value;draft.model='Custom';draft.trim='';render()" placeholder="Type make"></label>`:''}<label>Model<select id="model" onchange="draft.model=this.value;draft.customModel='';draft.trim='';draft.customTrim='';render()">${opts(withCustom(models),'Model',draft.model)}</select></label>${customModel?`<label>Custom model<input id="customModel" value="${esc(draft.customModel)}" oninput="draft.customModel=this.value;draft.trim='Custom';render()" placeholder="Type model"></label>`:''}<label>Submodel / trim<select id="trim" onchange="draft.trim=this.value;draft.customTrim='';render()">${opts(withCustom(trimList),'Submodel / trim',draft.trim)}</select></label>${customTrim?`<label>Custom submodel / trim<input id="customTrim" value="${esc(draft.customTrim)}" oninput="draft.customTrim=this.value" placeholder="Type trim"></label>`:''}</section><button class="bottomAction" onclick="go('package')">Next: W/O package →</button>`}
function packageScreen(){let p=state?.presets||fallback,items=p.work||fallback.work;return `<section class="stepHero"><span>Step 2 of 3</span><h1>Build the W/O</h1><p>Package first. Use Additions for extra W/O lines; choose Custom if the exact operation is missing.</p></section><section class="card formCard"><label>RO / ticket<input id="ro" value="${esc(draft.ro)}" oninput="draft.ro=this.value" placeholder="#12345"></label><label>Job package<select id="title" onchange="applyPackage(this.value)">${opts(Object.keys(packages),'Select package',selectedPackage)}</select></label><label>Additions<select id="itemSelect" onchange="draft.itemChoice=this.value;draft.customItem=this.value==='Custom'?draft.customItem:'';render()">${opts(withCustom(items),'Add addition',draft.itemChoice)}</select></label>${draft.itemChoice==='Custom'||draft.customItem?`<label>Custom addition<input id="customItem" value="${esc(draft.customItem)}" oninput="draft.customItem=this.value" placeholder="Manual W/O item"></label>`:''}<button class="secondary" onclick="addSelectedItem()">Add addition</button></section><section class="card"><h2>Selected W/O items</h2><div class="chips">${selectedItems.length?selectedItems.map((x,i)=>`<button class="chipBtn" onclick="removeItem(${i})">${esc(x)} ✕</button>`).join(''):'<p class="muted">Pick a package or add additions.</p>'}</div></section><button class="bottomAction" onclick="reviewFromPackage()">Next: Review →</button>`}
function pendingItem(){let sel=draft.itemChoice||$('#itemSelect')?.value||'';let manual=(draft.customItem||$('#customItem')?.value||'').trim();return sel==='Custom'?manual:(manual||sel)}
function commitPendingItem(){let v=pendingItem();if(v&&!selectedItems.includes(v)){selectedItems.push(v);draft.customItem='';draft.itemChoice='';return true}return false}
function reviewFromPackage(){commitPendingItem();go('review')}
function reviewScreen(){commitPendingItem();let vehicle=[draft.year,actualMake(),actualModel(),actualTrim()].filter(Boolean).join(' ')||'No vehicle selected';return `<section class="stepHero"><span>Step 3 of 3</span><h1>Review and start</h1><p>This creates one timer card for every package item and addition.</p></section><section class="card review"><span>Vehicle</span><b>${esc(vehicle)}</b><span>RO</span><b>${esc(draft.ro||'—')}</b><span>Package</span><b>${esc(selectedPackage||'Custom')}</b><span>W/O items</span><b>${selectedItems.length}</b></section><section class="card"><div class="chips">${selectedItems.map((x,i)=>`<button class="chipBtn" onclick="removeItem(${i})">${esc(x)} ✕</button>`).join('')||'<p class="muted">No W/O items yet.</p>'}</div></section><button class="bottomAction go" onclick="startJob()">Start W/O timers</button>`}
function workStartScreen(){let today=openScheduleItems(todayKey()),sel=openScheduleItems(selectedScheduleDate);return `<section class="stepHero work"><span>Work</span><h1>Pick a W/O</h1><p>Select from the calendar schedule or create a fresh W/O.</p></section><section class="card"><h2>Today's scheduled W/O</h2>${today.length?today.map(scheduleCard).join(''):'<p class="muted">No scheduled W/O for today.</p>'}</section>${selectedScheduleDate!==todayKey()?`<section class="card"><h2>${esc(selectedScheduleDate)} scheduled W/O</h2>${sel.length?sel.map(scheduleCard).join(''):'<p class="muted">No W/O on selected calendar day.</p>'}</section>`:''}<section class="bigGrid"><button class="mega" onclick="go('vehicle')">Create W/O</button><button class="mega secondary" onclick="go('schedule')">Open calendar</button></section>`}
function workScreen(){let j=job();if(!j)return workStartScreen();let p=state?.presets||fallback,stats=jobStats(j),run=activeTask(j),wait=openWait(j);return `${woTicket(j)}<section class="card"><div class="metrics three"><div><span>Total</span><b>${fmt(stats.total)}</b></div><div><span>Wrench</span><b>${fmt(stats.work)}</b></div><div><span>Waiting</span><b>${fmt(stats.wait)}</b></div></div><div class="bigGrid"><button class="go" onclick="go('focus')">Focus mode</button><button class="warn" onclick="api({action:'holdJob'}).then(()=>go('home'))">Park vehicle</button><button class="danger" onclick="api({action:'endJob'}).then(()=>go('home'))">Finish job</button></div></section><section class="card"><h2>W/O toggles</h2>${(j.tasks||[]).map(taskCard).join('')}</section><section class="card"><h2>Reason chips</h2><div class="chips reasonChips">${['Parts','Approval','Advisor','Customer','Rack','Road test','Double Torque'].map(x=>`<button class="chipBtn" onclick="startWait('${x}')">${x}</button>`).join('')}</div><div class="selectRow"><select id="waitQuick">${opts(p.downtime,'Wait reason')}</select><button class="warn" onclick="startWait($('#waitQuick').value||'Wait')">Start wait</button></div>${wait?`<button class="go" onclick="api({action:'endWait'})">Back on it: ${esc(wait.label)} ${fmt(ms(wait.start))}</button>`:''}<label>Bay note<textarea id="note" placeholder="Advisor pulled me, stripped lug, rack wait, customer declined…"></textarea></label><button class="secondary" onclick="addNote()">Add bay note</button></section>${jobTimeline(j)}`}
function taskCard(t){let st=statusLabel(t),live=st==='running';return `<div class="taskCard ${live?'live':''} ${st==='done'?'done':''}"><div><b>${esc(t.label)}</b><span>${esc(st)} • ${fmt(taskTotal(t))}</span></div><div class="toggleGrid"><button class="go" onclick="api({action:'${st==='running'?'pauseTask':'startTask'}',taskId:'${t.id}'})">${st==='running'?'Pause':'Start'}</button><button onclick="api({action:'continueTask',taskId:'${t.id}'})">Resume</button><button class="danger" onclick="api({action:'stopTask',taskId:'${t.id}'})">Done</button><button class="secondary" onclick="deleteTask('${t.id}')">Remove</button></div></div>`}
function statusLabel(t){let segs=t.segments||[];return segs.length&&!segs[segs.length-1].end?'running':t.status||'queued'}
function quickScreen(){let cat=qTools[quick.cat]||qTools.fluids,tool=cat.tools[quick.tool]||Object.values(cat.tools)[0],a=parseFloat(quick.a),b=parseFloat(quick.b),ok=Number.isFinite(a),res='—',catOpts=Object.entries(qTools).map(([k,c])=>`<option value="${k}" ${k===quick.cat?'selected':''}>${esc(c.label)}</option>`).join('');if(ok){let val=tool.two?tool.fn(a,Number.isFinite(b)?b:0):(quick.reverse&&tool.rev?tool.rev(a):tool.fn(a));res=Number.isFinite(val)?Number(val.toFixed(4)).toString():'—'}return `<section class="stepHero"><span>Quick view</span><h1>Shop calculator</h1><p>Always reachable from the top-right Quick button.</p></section><section class="card formCard"><label>Category<select onchange="quick.cat=this.value;quick.tool=Object.keys(qTools[this.value].tools)[0];quick.a='';quick.b='';render()">${catOpts}</select></label><label>Tool<select onchange="quick.tool=this.value;quick.a='';quick.b='';render()">${Object.entries(cat.tools).map(([k,t])=>`<option value="${k}" ${k===quick.tool?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><label>${esc(tool.unit)}<input inputmode="decimal" value="${esc(quick.a)}" oninput="quick.a=this.value;render()" placeholder="Enter value"></label>${tool.two?`<label>${esc(tool.two)}<input inputmode="decimal" value="${esc(quick.b)}" oninput="quick.b=this.value;render()" placeholder="Enter value"></label>`:`<label class="check"><input type="checkbox" ${quick.reverse?'checked':''} onchange="quick.reverse=this.checked;render()"> Reverse direction</label>`}</section><section class="answer"><span>${esc(tool.label)}</span><b>${res}</b><em>${quick.reverse&&!tool.two?esc(tool.unit):esc(tool.out)}</em></section>`}
function bookEditorCard(){let labels=new Set([...Object.keys(defaultBook),...fallback.work,...(state?.presets?.work||[]),...Object.keys(bookRates()),...opRows().map(r=>r.label)]);let list=[...labels].sort((a,b)=>a.localeCompare(b));return `<section class="card"><h2>Flat-rate (book) hours</h2><p class="muted">Set the sold/book hours per operation so efficiency can be tracked against actual time. Leave blank to use the shop default.</p>${list.map(label=>`<div class="listItem"><div><b>${esc(label)}</b><span>Default ${defaultBook[label]?defaultBook[label]+'h':'none'}${bookRates()[label]?' • custom set':''}</span></div><input style="max-width:100px" inputmode="decimal" value="${bookRates()[label]??''}" placeholder="${defaultBook[label]??''}" onchange="saveBook('${jsq(label)}',this.value)"></div>`).join('')}</section>`}
function accountCard(){let m=me();return `<section class="card formCard"><h2>Account</h2><p class="muted">Logged in as <b>${esc(m.username)}</b>${m.role==='admin'?' • admin':''}. Data is saved per user on this server.</p><label>Labor rate ($/hr)<input inputmode="decimal" value="${m.laborRate||''}" placeholder="e.g. 28" onchange="saveLaborRate(this.value)"></label><label>Efficiency goal (%)<input inputmode="decimal" value="${(m.goals||{}).targetEfficiencyPct||''}" placeholder="e.g. 95" onchange="saveGoal(this.value)"></label></section><section class="card formCard"><h2>Change password</h2><label>Current password<input id="pwCurrent" type="password" autocomplete="current-password"></label><label>New password<input id="pwNew" type="password" autocomplete="new-password"></label>${pwError?`<p style="color:var(--bad);font-weight:800">${esc(pwError)}</p>`:''}<button class="secondary" ${pwBusy?'disabled':''} onclick="changePasswordSubmit()">${pwBusy?'Saving…':'Change password'}</button><button class="danger" onclick="doLogout()">Log out</button></section>`}
function settingsScreen(){return `<section class="stepHero"><span>Settings</span><h1>Make it readable</h1><p>Theme choices and recurring work/off patterns live here.</p></section>${accountCard()}<section class="card formCard"><label>Color theme<select onchange="applyTheme(this.value);render()">${opts(['shop','light','dark','contrast'],'Theme',theme)}</select></label><button class="secondary" onclick="download()">Download backup JSON</button><button class="secondary" onclick="saveArchive()">Save GitHub-style month archive</button></section>${recurrenceEditor()}${bookEditorCard()}<section class="card"><h2>Month archive</h2><p class="muted">Save creates <b>archive/YYYY-MM/&lt;username&gt;/</b> with a timestamped snapshot and monthly-summary.json, plus an automatic save every time you clock out. Once this folder is in GitHub, it stays organized by month and by tech.</p></section><section class="card"><h2>One-finger flow</h2><p class="muted">Home → Vehicle → W/O Package → Review → Work timers. Back button goes one step back. Quick tools are available from every page.</p></section>`}
function allShifts(){return Object.values(state?.days||{}).flatMap(d=>(d.shifts||[]).map(s=>({...s,date:d.date})))}function opRows(){let rows=[];allShifts().forEach(s=>jobsOf(s).forEach(j=>{let js=jobStats(j);(j.tasks||[]).forEach(t=>{let dur=taskTotal(t);if((t.status==='done'||j.end)&&dur>0){let start=(t.segments||[])[0]?.start||j.start,dt=new Date(start);rows.push({label:t.label,dur,start,dt,day:s.date,weekday:dt.getDay(),hourBucket:hourBucketLabel(dt.getHours()),vehicle:j.vehicle||'No vehicle',ro:j.ro||'',job:j.title||'',bookMs:bookMsFor(t.label),jobWait:js.wait});}})}));return rows}
function avg(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0}function dateFiltered(rows){let now=Date.now();if(analyticsRange==='week')return rows.filter(r=>now-r.dt<7*86400000);if(analyticsRange==='month')return rows.filter(r=>now-r.dt<31*86400000);if(analyticsRange==='cars')return rows.sort((a,b)=>b.dt-a.dt).slice(0,8);return rows}
function csvEscape(x){return '"'+String(x??'').replaceAll('"','""')+'"'}function exportCsv(){let rows=opRows(),rate=me().laborRate||0,head=['day','weekday','hourBucket','vehicle','ro','job','operation','actualHours','bookHours','efficiencyPct','dollarsBilled'];let lines=[head.join(',')].concat(rows.map(r=>[r.day,weekdayNames[r.weekday],r.hourBucket,r.vehicle,r.ro,r.job,r.label,hrs(r.dur),r.bookMs?hrs(r.bookMs):'',r.bookMs?effPct(r.bookMs,r.dur):'',r.bookMs?dollars(r.bookMs,rate):''].map(csvEscape).join(',')));let a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(lines.join('\n'));a.download='torqueclock-ops-'+new Date().toISOString().slice(0,10)+'.csv';a.click()}function chartBars(ops){let max=Math.max(1,...ops.map(o=>o.avg));return `<div class="chartBars">${ops.slice(0,8).map(o=>`<div><span>${esc(o.label)}</span><i style="width:${Math.max(7,o.avg/max*100)}%"></i><b>${fmt(o.avg)}</b></div>`).join('')}</div>`}function saveArchive(){api({action:'archiveSnapshot'}).then(r=>{if(r.ok){let a=r.state.lastArchive;toast('Saved '+(a?.summary||'month archive'))}})}function repeatJobById(id){let j=allShifts().flatMap(s=>jobsOf(s)).find(x=>x.id===id);repeatJob(j)}function improvementOps(rows){let g=rows.reduce((m,r)=>{(m[r.label]||(m[r.label]=[])).push(r);return m},{});return Object.entries(g).map(([label,a])=>{a=a.sort((x,y)=>x.dt-y.dt);let mid=Math.max(1,Math.floor(a.length/2)),early=a.slice(0,mid),late=a.slice(mid);let e=avg(early.map(x=>x.dur)),l=avg((late.length?late:early).map(x=>x.dur));return{label,count:a.length,early:e,late:l,delta:e-l,pct:e?((e-l)/e*100):0}}).filter(x=>x.count>1).sort((a,b)=>b.pct-a.pct)}function improvementChart(rows){let ops=improvementOps(rows),max=Math.max(1,...ops.map(o=>Math.abs(o.pct)));return `<div class="improveChart">${ops.slice(0,6).map(o=>`<div><span>${esc(o.label)}</span><i class="${o.delta>=0?'good':'bad'}" style="width:${Math.max(8,Math.abs(o.pct)/max*100)}%"></i><b>${o.delta>=0?'↑':'↓'} ${Math.abs(o.pct).toFixed(0)}%</b><small>${fmt(o.early)} → ${fmt(o.late)}</small></div>`).join('')||'<p class="muted">Run an operation more than once to see improvement.</p>'}</div>`}function performanceTimeline(rows){let days={};rows.forEach(r=>{let k=r.day||r.dt.toISOString().slice(0,10);(days[k]||(days[k]={jobs:0,actual:0,book:0}));days[k].jobs++;days[k].actual+=r.dur;days[k].book+=r.bookMs});let pts=Object.entries(days).sort((a,b)=>a[0].localeCompare(b[0])).slice(-14);let max=Math.max(1,...pts.map(([_,d])=>Math.max(d.actual,d.book)));return `<div class="timelineChart">${pts.map(([day,d])=>`<div><span>${day.slice(5)}</span><i><em style="height:${Math.max(6,d.actual/max*100)}%"></em><strong style="height:${Math.max(6,d.book/max*100)}%"></strong></i><b>${d.jobs}</b></div>`).join('')||'<p class="muted">Timeline builds as jobs are completed.</p>'}</div><p class="muted legend"><span class="actual"></span> actual time <span class="book"></span> flat-rate/book time</p>`}function breakdownItems(rows,keyFn,order){let g={};rows.forEach(r=>{let k=keyFn(r);(g[k]||(g[k]=[])).push(r)});return order.map(k=>({key:k,agg:aggEff(g[k]||[])}))}
function breakdownBars(items){let max=Math.max(1,...items.map(i=>i.agg.hoursMs));return `<div class="chartBars">${items.map(i=>`<div><span>${esc(i.key)}</span><i style="width:${i.agg.hoursMs?Math.max(6,i.agg.hoursMs/max*100):3}%;background:${i.agg.pct==null?'var(--line)':i.agg.pct>=100?'var(--good)':i.agg.pct>=85?'var(--warn)':'var(--bad)'}"></i><b>${i.agg.hoursMs?hrs(i.agg.hoursMs)+'h ':''}${effLabel(i.agg.pct)}</b></div>`).join('')}</div>`}
function weekdayBreakdown(rows){return breakdownBars(breakdownItems(rows,r=>weekdayNames[r.weekday],weekdayNames))}
function hourBreakdown(rows){let order=hourBuckets.map(b=>b[0]),items=breakdownItems(rows,r=>r.hourBucket,order).filter(i=>i.agg.hoursMs||i.key!=='Other hours');return breakdownBars(items)}
function analyticsScreen(){let rows=dateFiltered(opRows()),g=rows.reduce((m,r)=>{(m[r.label]||(m[r.label]=[])).push(r);return m},{}),ops=Object.entries(g).map(([label,a])=>({label,count:a.length,avg:avg(a.map(x=>x.dur)),best:[...a].sort((x,y)=>x.dur-y.dur)[0],eff:aggEff(a).pct})).sort((a,b)=>a.avg-b.avg),overall=aggEff(rows),rate=me().laborRate||0,goal=(me().goals||{}).targetEfficiencyPct||95,billedDollars=overall.billed/3600000*rate,hoursWorked=overall.hoursMs/3600000,perClockHour=hoursWorked>0?billedDollars/hoursWorked:0;return `<section class="stepHero"><span>Stats</span><h1>Performance dashboard</h1><p>Charts show average times, improvement trends, and a daily timeline against book time. Efficiency is billed (book) hours ÷ actual hours.</p></section><section class="card formCard"><label>Range<select onchange="analyticsRange=this.value;render()"><option value="week" ${analyticsRange==='week'?'selected':''}>Last 7 days</option><option value="month" ${analyticsRange==='month'?'selected':''}>Last 31 days</option><option value="cars" ${analyticsRange==='cars'?'selected':''}>Last few cars</option><option value="all" ${analyticsRange==='all'?'selected':''}>All time</option></select></label></section><section class="card accent"><h2>Efficiency this range ${effChip(overall.pct)}</h2><div class="metrics three"><div><span>Hours worked</span><b>${hrs(overall.hoursMs)}h</b></div><div><span>Billed hours</span><b>${hrs(overall.billed)}h</b></div><div><span>Efficiency</span><b>${effLabel(overall.pct)}</b></div></div>${rate?`<div class="metrics two" style="margin-top:10px"><div><span>$ billed</span><b>$${billedDollars.toFixed(2)}</b></div><div><span>$ per clock hour</span><b>$${perClockHour.toFixed(2)}</b></div></div>`:'<p class="muted">Set your labor rate in Settings to see dollars billed.</p>'}<h2 style="margin-top:18px;font-size:1.1rem">Goal: ${goal}% efficiency</h2>${goalBar(overall.pct,goal)}</section><section class="card"><div class="actionRow"><button class="secondary" onclick="exportCsv()">Export CSV</button><button class="secondary" onclick="saveArchive()">Save month archive</button></div></section><section class="card proCard"><h2>${icon('chart')} Avg time chart</h2>${ops.length?chartBars(ops):'<p class="muted">Charts appear after completed W/O item timers.</p>'}</section><section class="card proCard"><h2>Improvement tracker</h2>${improvementChart(rows)}</section><section class="card proCard"><h2>Performance timeline</h2>${performanceTimeline(rows)}</section><section class="card proCard"><h2>Efficiency by day of week</h2>${weekdayBreakdown(rows)}</section><section class="card proCard"><h2>Efficiency by time of day</h2>${hourBreakdown(rows)}</section>${comebackCard()}${waitDragBreakdown()}<section class="card"><h2>Operations</h2>${ops.length?ops.map(o=>`<div class="listItem"><div><b>${esc(o.label)}</b><span>${o.count} done • avg ${fmt(o.avg)} • best ${fmt(o.best.dur)}</span></div>${effChip(o.eff)}</div>`).join(''):'<p class="muted">Finish W/O item timers to build stats.</p>'}</section>${resultsScreen()}`}
function periodJobs(){let now=Date.now(),today=new Date().toDateString(),all=allShifts().flatMap(s=>jobsOf(s));return{day:all.filter(j=>j.end&&new Date(j.end).toDateString()===today),week:all.filter(j=>j.end&&now-new Date(j.end)<7*86400000),month:all.filter(j=>j.end&&now-new Date(j.end)<31*86400000)}}
function periodOpRows(){let now=Date.now(),today=todayKey(),rows=opRows();return{day:rows.filter(r=>r.day===today),week:rows.filter(r=>now-r.dt<7*86400000),month:rows.filter(r=>now-r.dt<31*86400000)}}
function countOps(jobs){let m={};jobs.forEach(j=>(j.tasks||[]).forEach(t=>{if(taskTotal(t)>0)m[t.label]=(m[t.label]||0)+1}));return m}function opBadges(m){let a=Object.entries(m).sort((x,y)=>y[1]-x[1]||x[0].localeCompare(y[0])).slice(0,5);return a.length?a.map(([k,v])=>`<span>${v} ${esc(k)}</span>`).join(''):'<em>No ops yet</em>'}
function tallyPanel(){let p=periodJobs(),por=periodOpRows();return `<section class="card"><h2>Live tally</h2><div class="metrics three">${[['Today','day'],['7 days','week'],['31 days','month']].map(([n,k])=>`<div><span>${n}</span><b>${p[k].length}</b><small>${effChip(aggEff(por[k]).pct)}<br>${opBadges(countOps(p[k]))}</small></div>`).join('')}</div></section>`}
function resultsScreen(){let days=Object.values(state?.days||{}).sort((a,b)=>b.date.localeCompare(a.date)),ss=(days[0]?.shifts||[]);return `<section class="stepHero"><span>History</span><h1>Today / recent</h1><p>Edit missed punches or delete bad clock records.</p></section><section class="card">${ss.length?ss.map(s=>{let t=totals(s);return `<div class="listItem shiftEdit"><div><b>${tm(s.start)} - ${s.end?tm(s.end):'now'}</b><span>Work ${fmt(t.work)} • Wait ${fmt(t.wait)} • Break ${fmt(t.breaks)}</span><label>In<input id="shiftStart-${s.id}" type="datetime-local" value="${dtLocal(s.start)}"></label><label>Out<input id="shiftEnd-${s.id}" type="datetime-local" value="${dtLocal(s.end)}"></label></div><div class="miniBtns"><button class="secondary" onclick="editShift('${s.id}')">Save punch</button><button class="danger" onclick="deleteShift('${s.id}')">Delete</button></div></div>${jobsOf(s).map(jobResult).join('')}`}).join(''):'<p class="muted">No history yet.</p>'}</section>`}
function jobResult(j){let st=jobStats(j);return `<div class="historyJob"><b>${esc(j.vehicle||'Vehicle')}</b><span>${esc(j.title)} • ${fmt(st.total)}${j.comeback?` • <b style="color:var(--bad)">Comeback</b>${j.comebackNote?': '+esc(j.comebackNote):''}`:''}</span><div class="miniBtns"><button class="${j.comeback?'danger':'secondary'}" onclick="toggleComeback('${j.id}',${j.comeback?'true':'false'})">${j.comeback?'Unmark comeback':'Mark comeback'}</button><button class="secondary" onclick="deleteJob('${j.id}')">Remove</button></div></div>`}
function toggleComeback(id,current){let note='';if(!current)note=prompt('Comeback reason (optional):')||'';api({action:'setComeback',jobId:id,comeback:!current,note})}
function jobRows(){let rows=[];allShifts().forEach(s=>jobsOf(s).forEach(j=>{if(j.end)rows.push({...j,day:s.date,dt:new Date(j.end)})}));return rows}
function comebackCard(){let rows=dateFiltered(jobRows()),total=rows.length,cbRows=rows.filter(r=>r.comeback),cb=cbRows.length,pct=total?Math.round(cb/total*100):0,byOp={};cbRows.forEach(r=>{let k=r.title||'Shop job';byOp[k]=(byOp[k]||0)+1});let top=Object.entries(byOp).sort((a,b)=>b[1]-a[1]).slice(0,5);return `<section class="card"><h2>Comebacks</h2><div class="metrics two"><div><span>Comeback rate</span><b>${pct}%</b><small>${cb} of ${total} jobs</small></div><div><span>This range</span><b>${cb}</b><small>flagged as comebacks</small></div></div>${top.length?`<div class="chips" style="margin-top:12px">${top.map(([k,v])=>`<span class="pill">${v} ${esc(k)}</span>`).join('')}</div>`:'<p class="muted">Mark a job as a comeback from History to start tracking.</p>'}</section>`}
function applyPackage(v){if(v in packages){selectedPackage=v;selectedItems=[...packages[v]];toast(v==='Custom'?'Custom package: add W/O items below':'Package loaded');render()}}function addSelectedItem(){let v=(draft.customItem||$('#customItem')?.value||'').trim()||$('#itemSelect')?.value;if(v&&!selectedItems.includes(v)){selectedItems.push(v);draft.customItem='';render()}}function removeItem(i){selectedItems.splice(i,1);render()}
function startJob(){commitPendingItem();let make=actualMake().trim(),model=actualModel().trim(),trim=actualTrim().trim(),year=draft.year||'',items=selectedItems.slice();api({action:'startJob',make,model,trim,year,ro:draft.ro,title:selectedPackage||items.join(' + ')||'Shop job',items}).then(r=>{if(r.ok){selectedItems=[];selectedPackage='';draft={year:'',make:'',model:'',customMake:'',customModel:'',trim:'',customTrim:'',ro:'',customItem:'',itemChoice:''};go('work')}})}
function startWait(label){if(label)api({action:'startWait',label})}function editShift(id){api({action:'editShift',shiftId:id,start:isoFromLocal($('#shiftStart-'+id)?.value),end:isoFromLocal($('#shiftEnd-'+id)?.value)})}function deleteShift(id){if(confirm('Delete this clock in/out record and all jobs inside it?'))api({action:'deleteShift',shiftId:id})}function addNote(){api({action:'addNote',target:job()?'job':'shift',text:$('#note')?.value||''})}function deleteTask(id){if(confirm('Remove this W/O item and its timer data?'))api({action:'deleteTask',taskId:id})}function deleteJob(id){if(confirm('Remove this vehicle/job from today? This deletes its timers from the tally.'))api({action:'deleteJob',jobId:id})}function saveBook(label,val){let n=parseFloat(val);api({action:'setBookRate',label,hours:Number.isFinite(n)?n:0}).then(r=>{if(r.ok)toast('Flat-rate hours saved')})}function download(){let a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(state,null,2));a.download='torqueclock-'+new Date().toISOString().slice(0,10)+'.json';a.click()}
Object.assign(window,{go,back,api,applyPackage,addSelectedItem,removeItem,startJob,startWait,addNote,deleteTask,deleteJob,saveBook,download,exportCsv,saveArchive,repeatJobById,reviewFromPackage,editShift,deleteShift,setSchedulePackage,addScheduleItemChip,removeScheduleItemChip,saveScheduledWorkOrder,startScheduledWorkOrder,deleteScheduledWorkOrder,selectScheduleDate,monthShift,toggleRecurrenceDay,setRecurrenceDay,applyRecurringSchedule,dayScreen,selectedDayDropdown,focusScreen,nowBar,authSubmit,switchAuthMode,doLogout,changePasswordSubmit,saveLaborRate,saveGoal,toggleComeback});
